// 02 assign working area status
//
// Input:
// msg.payload = normalized trolley rows
//
// Output:
// msg.payload = trolley rows with location_status
//
// This node does not filter rows.
// It only assigns:
// - in_workingarea
// - not_in_workingarea

const WORKING_AREA_MIN = 10000;
const WORKING_AREA_MAX = 27000;

function isInWorkingArea(position) {
    const pos = Number(position);

    return Number.isFinite(pos)
        && pos >= WORKING_AREA_MIN
        && pos <= WORKING_AREA_MAX;
}

msg.payload = (msg.payload || []).map(row => {
    const inArea = isInWorkingArea(row.actual_position);

    return {
        ...row,
        location_status: inArea ? "in_workingarea" : "not_in_workingarea"
    };
});

const inCount = msg.payload.filter(row => row.location_status === "in_workingarea").length;
const outCount = msg.payload.filter(row => row.location_status === "not_in_workingarea").length;

node.status({
    fill: inCount > 0 ? "green" : "yellow",
    shape: "dot",
    text: `working area: ${inCount} in / ${outCount} out`
});

return msg;

let token = msg.payload.token;

// Token im Flow-Context cachen (60 min)
flow.set("auth_token", token);
flow.set("auth_token_expiry", Date.now() + 60 * 60 * 1000);

msg.headers = {
    "Authorization": "Bearer " + token
};
msg.payload = msg.payload_org;

return msg;

// 03 detect location status changes
//
// Input:
// msg.payload = trolley rows with location_status
//
// Output:
// msg.payload = only rows where location_status changed
//
// Why this exists:
// The backend uses state_events as lifecycle events.
// Node-RED must not send the same location state on every snapshot.
// It should only send an event when a trolley enters or leaves the working area.

const rows = Array.isArray(msg.payload) ? msg.payload : [];

// Node context keeps last known location status per trolley.
// Example:
// {
//   "1": "not_in_workingarea",
//   "2": "in_workingarea"
// }
const previousStatusByTrolley = context.get("previousStatusByTrolley") || {};

const changes = [];

for (const row of rows) {
    const trolleyNo = row.trolley_no;
    const currentStatus = row.location_status;

    if (!Number.isInteger(trolleyNo)) {
        continue;
    }

    if (currentStatus !== "in_workingarea" && currentStatus !== "not_in_workingarea") {
        continue;
    }

    const previousStatus = previousStatusByTrolley[trolleyNo];

    // First observation:
    // Store status but do not send an event.
    // This avoids creating 32 events immediately after deploy/restart.
    if (previousStatus === undefined) {
        previousStatusByTrolley[trolleyNo] = currentStatus;
        continue;
    }

    // No change:
    // Do nothing.
    if (previousStatus === currentStatus) {
        continue;
    }

    // Real edge detected:
    // Send one state event.
    changes.push({
        ...row,
        previous_location_status: previousStatus,
        new_location_status: currentStatus
    });

    previousStatusByTrolley[trolleyNo] = currentStatus;
}

context.set("previousStatusByTrolley", previousStatusByTrolley);

const changedNos = changes.map(row => row.trolley_no).join(", ");

node.status({
    fill: changes.length > 0 ? "blue" : "grey",
    shape: "dot",
    text: changes.length > 0
        ? `location changes: ${changes.length} [${changedNos}]`
        : "location changes: 0"
});

msg.payload = changes;

return msg;

