// 01 normalize trolley array
//
// Input:
// msg.payload.ts
// msg.payload.value = raw trolley array from OPC UA / iotbridge
//
// Output:
// msg.payload = normalized trolley rows
//
// Important:
// In the current raw payload:
// - value[0] is a dummy / empty trolley row
// - value[1] is Trolley-01
// - value[2] is Trolley-02
// - ...
// - value[32] is Trolley-32

const sourceTs =
    typeof msg.payload?.ts === "string" && msg.payload.ts.trim() !== ""
        ? msg.payload.ts
        : new Date().toISOString();

const rawArray = Array.isArray(msg.payload?.Trolley_Data)
    ? msg.payload.Trolley_Data
    : Array.isArray(msg.payload?.value)
        ? msg.payload.value
        : [];

function isNonEmptyString(value) {
    return typeof value === "string" && value.trim() !== "";
}

function normalizeText(value) {
    return isNonEmptyString(value) ? value.trim() : "";
}

function toNumberOrNull(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function getActualPosition(row) {
    return toNumberOrNull(row.ActualPosition);
}

function getToolName(row, slotIndex) {
    const tool = Array.isArray(row.Tool) ? row.Tool[slotIndex] : null;

    if (!tool) {
        return "";
    }

    return normalizeText(
        tool?.Status_Tool?.Name_Tool ||
        tool?.RecipeData?.ToolNmbr ||
        ""
    );
}

function getToolApplied(row) {
    return Boolean(row.ToolApplied);
}

function getTrolleyNo(index, arrayLength) {
    // Current payload has 33 rows:
    // index 0 = dummy
    // index 1 = Trolley-01
    // index 32 = Trolley-32
    if (arrayLength === 33) {
        return index;
    }

    // Fallback if vendor payload changes to exactly 32 rows:
    // index 0 = Trolley-01
    if (arrayLength === 32) {
        return index + 1;
    }

    // Safe fallback for unexpected shape.
    return index > 0 ? index : null;
}

msg.payload = rawArray
    .map((row, index) => {
        const trolleyNo = getTrolleyNo(index, rawArray.length);

        return {
            trolley_no: trolleyNo,
            actual_position: getActualPosition(row),
            tool_0_name: getToolName(row, 0),
            tool_1_name: getToolName(row, 1),
            tool_applied: getToolApplied(row),
            ts: sourceTs,
            raw_index: index
        };
    })
    .filter(row => {
        return Number.isInteger(row.trolley_no)
            && row.trolley_no >= 1
            && row.trolley_no <= 32;
    });

node.status({
    fill: msg.payload.length === 32 ? "green" : "yellow",
    shape: "dot",
    text: `normalized ${msg.payload.length}/32 trolleys`
});

return msg;
